    clearTimeout(t);
    root.dataset.state = 'idle';
    void btn.offsetWidth;
    root.dataset.state = 'go';
    live.textContent = '준비됐어요';
    t = setTimeout(function () { if (root.isConnected) { root.dataset.state = 'idle'; live.textContent = ''; } }, rm ? 900 : 1900);
  });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var btn = root.querySelector('.u003-btn');
  var file = root.querySelector('.u003-file');
  var done = root.querySelector('.u003-done');
  var undo = root.querySelector('.u003-undo');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var HOLD = 1200;
  var p = 0, raf = 0, last = 0, holding = false, finished = false;

  function set(v) { p = v; btn.style.setProperty('--p', v.toFixed(4)); }
  // 누르는 동안 채움이 차오르고, 손을 떼면 같은 속도의 두 배로 빠지며 돌아갑니다
  function tick(now) {
    if (!root.isConnected) return;
    var dt = now - (last || now);
    last = now;
    if (holding) set(Math.min(1, p + dt / HOLD));
    else set(Math.max(0, p - dt / (HOLD / 2.4)));
    btn.style.setProperty('--shake', holding && p > 0.55 && !rm ? 'running' : 'paused');
    if (p >= 1 && holding) { complete(); return; }
    if (holding || p > 0) raf = requestAnimationFrame(tick);
    else { raf = 0; last = 0; }
  }
  function start() {
    if (finished) return;
    holding = true;
    btn.classList.add('is-holding');
    if (!raf) { last = 0; raf = requestAnimationFrame(tick); }
  }
  function stop() {
    holding = false;
    btn.classList.remove('is-holding');
    if (!raf && p > 0) raf = requestAnimationFrame(tick);
  }
  function complete() {
    holding = false; finished = true; raf = 0; last = 0;
    btn.classList.remove('is-holding');
    file.classList.add('is-gone');
    btn.classList.add('is-gone');
    btn.setAttribute('tabindex', '-1');
    done.classList.add('is-on');
    undo.focus({ preventScroll: true });
  }
  function restore() {
    finished = false;
    set(0);
    file.classList.remove('is-gone');
    btn.classList.remove('is-gone');
    btn.removeAttribute('tabindex');
    done.classList.remove('is-on');
    btn.focus({ preventScroll: true });
  }
  btn.addEventListener('pointerdown', function (e) { if (e.button === 0) { btn.setPointerCapture(e.pointerId); start(); } });
  btn.addEventListener('pointerup', stop);
  btn.addEventListener('pointercancel', stop);
  btn.addEventListener('lostpointercapture', stop);
  btn.addEventListener('contextmenu', function (e) { e.preventDefault(); });
  // 키보드는 Space나 Enter를 누르고 있는 동안 차오릅니다
  btn.addEventListener('keydown', function (e) {
    if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); if (!e.repeat) start(); }
  });
  btn.addEventListener('keyup', function (e) { if (e.key === ' ' || e.key === 'Enter') stop(); });
  btn.addEventListener('blur', stop);
  btn.addEventListener('click', function (e) { e.preventDefault(); });
  undo.addEventListener('click', restore);
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var btn = root.querySelector('.u004-btn');
  var pct = root.querySelector('.u004-pct');
  var eta = root.querySelector('.u004-eta');
  var live = root.querySelector('.u004-live');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var raf = 0, timers = [], p = 0, t0 = 0, DUR = rm ? 600 : 3200;
  function later(fn, ms) { timers.push(setTimeout(function () { if (root.isConnected) fn(); }, ms)); }
  function clear() { timers.forEach(clearTimeout); timers = []; cancelAnimationFrame(raf); raf = 0; }
  function set(v) {
    p = v;
    btn.style.setProperty('--p', v.toFixed(4));
    pct.textContent = Math.round(v * 100) + '%';
  }
  // 실제 네트워크처럼 빨라졌다 느려졌다 하는 진행 곡선입니다
  function curve(x) { return Math.min(1, x + Math.sin(x * Math.PI * 3) * 0.045 * (1 - x)); }
  function step(now) {
    if (!root.isConnected) return;
    var x = Math.min(1, (now - t0) / DUR);
    set(curve(x));
    var left = Math.max(0, Math.ceil((1 - x) * DUR / 1000 * 2.2));
    eta.textContent = left > 0 ? '남은 시간 ' + left + '초' : '마무리하는 중';
    if (x < 1) raf = requestAnimationFrame(step);
    else finish();
  }
  function finish() {
    root.dataset.state = 'fold';
    live.textContent = '다운로드 완료';
    later(function () { root.dataset.state = 'done'; }, rm ? 100 : 650);
    later(reset, rm ? 1600 : 3400);
  }
  function reset() { clear(); root.dataset.state = 'idle'; set(0); live.textContent = ''; }
  btn.addEventListener('click', function () {
    var s = root.dataset.state;
    if (s === 'run') { // 받는 중에 누르면 취소하고 처음으로 돌아갑니다
      clear();
      root.dataset.state = 'idle';
      set(0);
      live.textContent = '다운로드를 취소했어요';
      return;
    }
    if (s !== 'idle') { reset(); return; }
    clear();
    set(0);
    root.dataset.state = 'run';
    live.textContent = '다운로드 시작';
    later(function () { t0 = performance.now(); raf = requestAnimationFrame(step); }, rm ? 0 : 260);
  });
})();

(function () {
