      setTimeout(function () { fp.remove(); tr.style.opacity = '0'; }, dur + 80);
    }
    setTimeout(function () {
      btn.classList.remove('fly'); btn.classList.add('done');
      st.firstChild.textContent = '전송됨'; st.classList.add('ok');
    }, dur ? dur - 100 : 0);
    setTimeout(function () {
