  root.querySelector('.u007-arc').style.stroke = 'url(#' + gid + ')';

  // 삼각형을 두 조각으로 나눠, 각 꼭짓점을 일시정지 막대의 꼭짓점으로 옮깁니다
  var PLAY = [[[13, 8], [22.5, 13.6], [22.5, 26.4], [13, 32]], [[22.5, 13.6], [32, 20], [32, 20], [22.5, 26.4]]];
  var PAUSE = [[[11, 9], [17, 9], [17, 31], [11, 31]], [[23, 9], [29, 9], [29, 31], [23, 31]]];
  var shape = 0, raf = 0;
  function draw(t) {
    [L, R].forEach(function (poly, k) {
      poly.setAttribute('points', PLAY[k].map(function (p, j) {
        var q = PAUSE[k][j];
        return (p[0] + (q[0] - p[0]) * t).toFixed(2) + ',' + (p[1] + (q[1] - p[1]) * t).toFixed(2);
      }).join(' '));
