  var N = 44, bars = [];
  for (var i = 0; i < N; i++) {
    var b = document.createElement('i');
    var h = 30 + Math.abs(Math.sin(i * 0.9) * 46 + Math.sin(i * 0.37) * 24);
    b.style.setProperty('--h', Math.min(100, h).toFixed(0));
