    if (!root.isConnected || !playing) return;
    pos += (now - (last || now)) / 1000;
    last = now;
    if (pos >= TOTAL) { pos = 0; }
    render();
    loop = requestAnimationFrame(tick);
  }
  function setPlay(v) {
    playing = v;
    root.classList.toggle('is-play', v);
    btn.setAttribute('aria-pressed', String(v));
