  // 파형을 누르거나 끌어서 위치를 옮깁니다. 방향키는 5초씩 움직입니다
  function seek(x) {
    var r = wave.getBoundingClientRect();
    pos = Math.max(0, Math.min(1, (x - r.left) / r.width)) * TOTAL;
    render();
  }
  wave.addEventListener('pointerdown', function (e) { wave.setPointerCapture(e.pointerId); seek(e.clientX); });
  wave.addEventListener('pointermove', function (e) { if (wave.hasPointerCapture(e.pointerId)) seek(e.clientX); });
